[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$JobRoot,[Parameter(Mandatory=$true)][string]$RepositoryRoot,[string]$AttemptId='oracle-v1',[switch]$Smoke,[ValidateSet('720p','1080p','1440p','4k')][string]$SmokeResolution='720p')
$ErrorActionPreference='Stop';$JobRoot=[IO.Path]::GetFullPath($JobRoot);$RepositoryRoot=[IO.Path]::GetFullPath($RepositoryRoot)
if(-not $JobRoot.StartsWith('D:\CodexLab\',[StringComparison]::OrdinalIgnoreCase)){throw 'D: job required'}
$g21=Join-Path $RepositoryRoot 'scripts\generate-fg-connected-dynamic-l3-l21.py';$g23=Join-Path $RepositoryRoot 'scripts\generate-fg-connected-dynamic-l3-l23.py';$harness=Join-Path $RepositoryRoot 'scripts\build-fg-connected-dynamic-l3-l23-rtx.ps1';$modules=Join-Path $JobRoot 'inputs\modules';$attempt=Join-Path $JobRoot "output\$AttemptId";$build=Join-Path $attempt 'build'
foreach($p in @($g21,$g23,$harness)){if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw "missing $p"}}
if(Test-Path $attempt){throw 'attempt exists'}
$w63=Join-Path $modules 'default-token-000063.bin';$w65=Join-Path $modules 'default-token-000065.bin';$m30=Join-Path $modules 'cu-module-000030.bin'
if((Get-FileHash $w63 -Algorithm SHA256).Hash.ToLowerInvariant()-ne'44595b02307a6b934a124abe476cfd327440e2acba7f5ed69f73195ca743e3d9'){throw'weight63'}
if((Get-FileHash $w65 -Algorithm SHA256).Hash.ToLowerInvariant()-ne'eb99328524fddc9f5f3fac12b8e3a4011e66a75e071cd07126a70c553458bc60'){throw'weight65'}
if((Get-FileHash $m30 -Algorithm SHA256).Hash.ToLowerInvariant()-ne'31bb08d04011db9a0def8f1a1bc3999efc08d5deb8d7cb9b5debf52ec489b785'){throw'module30'}
$started=(Get-Date).ToUniversalTime().ToString('o');New-Item -ItemType Directory -Path $build|Out-Null
& python $g21 --repository $RepositoryRoot --output (Join-Path $build 'base-generated');if($LASTEXITCODE){throw'g21'}
& python $g23 --base (Join-Path $build 'base-generated') --output (Join-Path $build 'generated');if($LASTEXITCODE){throw'g23'}
$source=Join-Path $build 'generated\generated_rtx.cpp';$cuda=if($env:CUDA_PATH){$env:CUDA_PATH}else{'C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v13.3'};$vs=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe';$install=&$vs -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath;$vc=Join-Path $install 'VC\Auxiliary\Build\vcvars64.bat';$env:TEMP=$build;$env:TMP=$build;$exe=Join-Path $build 'host.exe';$obj=Join-Path $build 'host.obj';$log=Join-Path $build 'compile.log';$inc0=Join-Path $RepositoryRoot 'src';$inc1=Join-Path $RepositoryRoot 'src\fg_connected_dynamic_early';$inc2=Join-Path $RepositoryRoot 'src\fg_connected_dynamic_l3_l21';$cmd='"{0}" >nul && cl /nologo /std:c++20 /EHsc /MD /W4 /WX /permissive- /Zc:__cplusplus /utf-8 /I"{1}" /I"{2}" /I"{3}" /Fo"{4}" /c "{5}" >"{6}" 2>&1 && link /nologo /OUT:"{7}" "{4}" bcrypt.lib d3d12.lib dxgi.lib >>"{6}" 2>&1'-f$vc,$inc0,$inc1,$inc2,$obj,$source,$log,$exe;&$env:ComSpec /d /s /c $cmd;if($LASTEXITCODE){throw"compile $log"}
$res=if($Smoke){@($SmokeResolution)}else{@('720p','1080p','1440p','4k')};$zs=if($Smoke){@('a5')}else{@('a5','5a')};$os=if($Smoke){@('a')}else{@('a','b')};$receipts=@()
foreach($r in $res){foreach($z in $zs){foreach($o in $os){$id="$r-poison-$z-process-$o";$d=Join-Path $attempt $id;mkdir $d|Out-Null;$art=if($z-eq'a5'-and$o-eq'a'){'full'}else{'hash-only'};$p=Start-Process $exe -ArgumentList @($modules,$d,$id,$z,$r,$art) -Wait -PassThru -NoNewWindow -RedirectStandardOutput (Join-Path $d 'stdout.log') -RedirectStandardError (Join-Path $d 'stderr.log');if($p.ExitCode){throw"run $id"};$receipts+=Get-Content (Join-Path $d 'run-receipt.json') -Raw|ConvertFrom-Json}}}
$count=if($Smoke){1}else{16};if(@($receipts.process_id|sort -Unique).Count-ne$count){throw'pids'}
if(-not $Smoke){foreach($r in $res){$s=@($receipts|Where-Object{$_.resolution -eq $r});foreach($n in $s[0].checkpoint_sha256.PSObject.Properties.Name){if(@($s|ForEach-Object{$_.checkpoint_sha256.$n}|Sort-Object -Unique).Count -ne 1){throw"drift $r $n"}}}}
$rig=[ordered]@{schema='neuralstudio.fg.connected-dynamic-l3-l23-rig.v1';job_id=Split-Path -Leaf $JobRoot;attempt_id=$AttemptId;smoke=[bool]$Smoke;started_utc=$started;completed_utc=(Get-Date).ToUniversalTime().ToString('o');exit_code=0;gpu=(& nvidia-smi --query-gpu=name,driver_version,memory.total,pci.bus_id --format=csv,noheader,nounits|Select-Object -First 1).Trim();generator21_sha256=(Get-FileHash $g21 -Algorithm SHA256).Hash.ToLowerInvariant();generator23_sha256=(Get-FileHash $g23 -Algorithm SHA256).Hash.ToLowerInvariant();generator21_receipt_sha256=(Get-FileHash -LiteralPath (Join-Path $build 'base-generated\generator-receipt.json') -Algorithm SHA256).Hash.ToLowerInvariant();generator23_receipt_sha256=(Get-FileHash -LiteralPath (Join-Path $build 'generated\generator-receipt.json') -Algorithm SHA256).Hash.ToLowerInvariant();generated_source_sha256=(Get-FileHash $source -Algorithm SHA256).Hash.ToLowerInvariant();tail21_sha256=(Get-FileHash -LiteralPath (Join-Path $RepositoryRoot 'src\fg_connected_dynamic_l3_l21\rtx_tail.inc') -Algorithm SHA256).Hash.ToLowerInvariant();tail23_sha256=(Get-FileHash -LiteralPath (Join-Path $RepositoryRoot 'src\fg_connected_dynamic_l3_l23\rtx_tail.inc') -Algorithm SHA256).Hash.ToLowerInvariant();harness_sha256=(Get-FileHash $harness -Algorithm SHA256).Hash.ToLowerInvariant();weight63_sha256=(Get-FileHash $w63 -Algorithm SHA256).Hash.ToLowerInvariant();weight65_sha256=(Get-FileHash $w65 -Algorithm SHA256).Hash.ToLowerInvariant();module30_sha256=(Get-FileHash $m30 -Algorithm SHA256).Hash.ToLowerInvariant();run_count=$receipts.Count;fresh_process_count=@($receipts.process_id|Sort-Object -Unique).Count;selected_launches_per_process=25;live_device_handoffs=$true;expected_or_archived_intermediate_ingress=$false;address_fields_recorded=$false;result='pass'};$utf8=New-Object System.Text.UTF8Encoding($false);$rp=Join-Path $attempt 'rig-receipt.json';[IO.File]::WriteAllText($rp,(($rig|ConvertTo-Json -Depth 6)+"`n"),$utf8);Write-Host "attempt_root=$attempt";Write-Host result=pass
